_RD_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _rd_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        if open_paren and word in RD_METHODS:
            return "." + RD_METHODS[word] + open_paren
        if word in RD_PROPS:
            return "." + RD_PROPS[word]
        return match.group(0)
    if word in RD_CONSTS:
        return RD_CONSTS[word]
    if word in RD_FUNCS:
        return RD_FUNCS[word] + (open_paren or "")
    return match.group(0)


def RD_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _RD_TOKEN.sub(_rd_replace, text)
